-- 3. Price list header (DRAFT until approved). Confirm the effective date: 2027-01-01
DECLARE @PriceListId int = (SELECT PriceListId FROM billing.PriceList WHERE Name = N'CY2027');
IF @PriceListId IS NULL BEGIN
    SET @PriceListId = SCOPE_IDENTITY();
END
ELSE IF EXISTS (SELECT 1 FROM billing.PriceList WHERE PriceListId = @PriceListId AND Status <> N'DRAFT')
    THROW 50001, N'Price list CY2027 is no longer DRAFT; create a new price list instead of reloading.', 1;

-- 4. Prices (NULL = not priced; the application refuses to charge an unpriced code)
DELETE FROM billing.PriceListItem WHERE PriceListId = @PriceListId;

